import{_ as t,o as a,c as s,a4 as i}from"./chunks/framework.DA9C4Pbl.js";const g=JSON.parse('{"title":"Receiving transient alerts (NASA GCN and Fink)","description":"","frontmatter":{"title":"Receiving transient alerts (NASA GCN and Fink)","visibility":"public","audience":"operator","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/operating/transient-alerts.md","filePath":"guides/operating/transient-alerts.md"}'),n={name:"guides/operating/transient-alerts.md"};function o(r,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="receiving-transient-alerts-nasa-gcn-and-fink" tabindex="-1">Receiving transient alerts (NASA GCN and Fink) <a class="header-anchor" href="#receiving-transient-alerts-nasa-gcn-and-fink" aria-label="Permalink to “Receiving transient alerts (NASA GCN and Fink)”">​</a></h1><p>Your installation can listen to two streams of transient events:</p><ul><li>NASA&#39;s <a href="https://gcn.nasa.gov" target="_blank" rel="noreferrer">General Coordinates Network</a> (GCN), over which space observatories announce gamma-ray bursts (Swift, SVOM, Fermi), X-ray transients (Einstein Probe), neutrinos (IceCube) and gravitational waves (LIGO, Virgo, KAGRA). Alerts arrive as database rows within seconds of the downlink and feed the Target-of-Opportunity features.</li><li><a href="https://fink-broker.org" target="_blank" rel="noreferrer">Fink</a>, an alert broker that sorts the nightly detections of the ZTF sky survey by science case. Your installation receives the selection made for small telescopes: see <a href="#fink">Survey alerts from Fink</a>.</li></ul><p>Both run in the same optional service. GCN waits for credentials of your own; Fink needs none and starts with the service. If you skipped the service during <code>arcsecond setup</code>, re-run:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with-alerts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h2 id="network-prerequisites" tabindex="-1">Network prerequisites <a class="header-anchor" href="#network-prerequisites" aria-label="Permalink to “Network prerequisites”">​</a></h2><p>The consumer opens outbound, encrypted connections to five names, and listens on nothing:</p><table tabindex="0"><thead><tr><th>Name</th><th>Port</th><th>What for</th></tr></thead><tbody><tr><td><code>auth.gcn.nasa.gov</code></td><td>443</td><td>signing in</td></tr><tr><td><code>kafka.gcn.nasa.gov</code></td><td>9092</td><td>the first contact, which hands out the three names below</td></tr><tr><td><code>kafka1.gcn.nasa.gov</code>, <code>kafka2.gcn.nasa.gov</code>, <code>kafka3.gcn.nasa.gov</code></td><td>9092</td><td>the alerts themselves</td></tr></tbody></table><p>That is the complete list to hand your IT department if the observatory network is restricted. Note the port: <code>9092</code> is not a web port, and a network that only lets web traffic out blocks it. It cannot go through a web proxy.</p><h2 id="get-your-gcn-credentials-about-two-minutes-once-per-installation" tabindex="-1">Get your GCN credentials (about two minutes, once per installation) <a class="header-anchor" href="#get-your-gcn-credentials-about-two-minutes-once-per-installation" aria-label="Permalink to “Get your GCN credentials (about two minutes, once per installation)”">​</a></h2><p>GCN identifies each consumer individually — there are no shared Arcsecond credentials. Your installation gets its own identity, its own quota, and its own revocation switch.</p><ol><li>Sign in (or create an account) at <a href="https://gcn.nasa.gov/quickstart" target="_blank" rel="noreferrer">https://gcn.nasa.gov/quickstart</a>.</li><li>Follow the <em>Start streaming GCN Notices</em> flow to create <strong>client credentials</strong>. When asked for a scope, select <strong><code>gcn.nasa.gov/kafka-public-consumer</code></strong>.</li><li>Copy the <strong>client ID</strong> and <strong>client secret</strong> it shows you.</li></ol><h2 id="configure" tabindex="-1">Configure <a class="header-anchor" href="#configure" aria-label="Permalink to “Configure”">​</a></h2><p>Open the <code>.env</code> file in your Arcsecond folder and paste the two values:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GCN_CONSUMER_CLIENT_ID=your-client-id</span></span>
<span class="line"><span>GCN_CONSUMER_CLIENT_SECRET=your-client-secret</span></span></code></pre></div><p>Then recreate just the alerts service, so it reads them:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alerts</span></span></code></pre></div><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to “Verify”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alerts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>Within about a minute you should see:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GCN consumer started (group.id=io.arcsecond.local.…, 32 topics).</span></span>
<span class="line"><span>GCN connection established (heartbeat received).</span></span></code></pre></div><p>The heartbeat line repeats at most once per hour — that is the liveness signal. Real alerts are rare; a quiet log between heartbeats is normal and correct. Ctrl-C leaves the log; the service keeps running.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Meaning and next action</th></tr></thead><tbody><tr><td><code>arcsecond status</code> does not list <code>alerts</code></td><td>The service is not in your <code>docker-compose.yml</code>. Run <code>arcsecond setup --with-alerts</code>, then <code>arcsecond start</code>.</td></tr><tr><td>Log says <code>GCN credentials not configured — transient alerts disabled</code></td><td>The two <code>.env</code> keys are empty. Follow <em>Configure</em> above, then <code>arcsecond restart alerts</code>.</td></tr><tr><td>Repeated authentication/SASL errors in the log</td><td>GCN rejected your credentials. Re-create them at <a href="https://gcn.nasa.gov/quickstart" target="_blank" rel="noreferrer">https://gcn.nasa.gov/quickstart</a> (check the scope is <code>gcn.nasa.gov/kafka-public-consumer</code>), update <code>.env</code>, then <code>arcsecond restart alerts</code>.</td></tr><tr><td>Connected, but no heartbeat line</td><td>An outbound connection to the names above is likely blocked, most often port 9092. Test from the host: <code>curl -sI https://auth.gcn.nasa.gov</code>, then <code>curl -v telnet://kafka.gcn.nasa.gov:9092</code> (it must say <em>Connected</em>).</td></tr><tr><td>Log says <code>Installation not initialized</code></td><td>The backend has not completed its first boot yet. Run <code>arcsecond start</code>, which waits for the backend to be ready, then <code>arcsecond restart alerts</code>.</td></tr></tbody></table><h2 id="fink" tabindex="-1">Survey alerts from Fink <a class="header-anchor" href="#fink" aria-label="Permalink to “Survey alerts from Fink”">​</a></h2><p>Fink, run by the IJCLab in France, reads every alert of the Zwicky Transient Facility (ZTF) and publishes them by science case, one stream per selection. Your installation subscribes to the selections a small telescope can follow, a few hundred events a night: early type Ia supernova candidates, supernova candidates, fast risers, kilonova candidates, microlensing candidates, and ZTF objects already classified on the Transient Name Server.</p><p>Each object becomes one event named by its ZTF id (<code>ZTF26abzidlp</code>), with one entry per detection, its latest magnitude, and Fink&#39;s classification scores. You can turn any of them into a target. Observing policies do not take survey events yet; when they do, a policy will have to name the survey explicitly, so an existing policy never starts receiving them on its own.</p><p>Survey events are kept for 30 days after their last detection, then removed, unless a target names them or an alert refers to them. GCN events are never removed.</p><p>Rubin Observatory (LSST) alerts will follow the same path once Arcsecond reads them.</p><h3 id="network-prerequisites-1" tabindex="-1">Network prerequisites <a class="header-anchor" href="#network-prerequisites-1" aria-label="Permalink to “Network prerequisites”">​</a></h3><p>The consumer opens outbound connections on port <code>24499</code>, and listens on nothing:</p><table tabindex="0"><thead><tr><th>Name</th><th>Port</th><th>What for</th></tr></thead><tbody><tr><td><code>kafka-ztf.fink-broker.org</code></td><td>24499</td><td>the first contact, which hands out the addresses below</td></tr><tr><td><code>157.136.249.242</code>, <code>157.136.252.46</code>, <code>157.136.252.125</code>, <code>157.136.252.183</code>, <code>157.136.253.223</code></td><td>24499</td><td>the alerts themselves (addresses as of October 2026)</td></tr></tbody></table><p>These connections are not encrypted: the alerts are public data. As with GCN&#39;s port 9092, <code>24499</code> is not a web port, and it cannot go through a web proxy.</p><h3 id="configure-1" tabindex="-1">Configure <a class="header-anchor" href="#configure-1" aria-label="Permalink to “Configure”">​</a></h3><p>Nothing to do: Fink&#39;s stream is open to read, and your installation names its own consumer after its machine, so that it never shares a stream with another installation. Two optional lines in <code>.env</code> change the defaults:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Turn Fink off; GCN keeps running.</span></span>
<span class="line"><span>FINK_ENABLED=false</span></span>
<span class="line"><span># Your own selection instead of the one above: Fink&#39;s topic names, comma-separated, each ending in _ztf.</span></span>
<span class="line"><span>FINK_TOPICS=fink_sn_candidates_ztf,fink_kn_candidates_ztf</span></span></code></pre></div><p>After changing either, run <code>arcsecond restart alerts</code>.</p><h3 id="verify-1" tabindex="-1">Verify <a class="header-anchor" href="#verify-1" aria-label="Permalink to “Verify”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alerts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>Within about a minute you should see:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Fink ZTF consumer started (group.id=arcsecond-local-…, 8 topics).</span></span>
<span class="line"><span>Fink ZTF connection established (80 partitions assigned).</span></span></code></pre></div><p>The group id is <code>arcsecond-local-</code> followed by your installation&#39;s machine fingerprint, which no other installation shares.</p><p>ZTF observes from California: alerts arrive during the night there, and an empty log during the European day is normal.</p><h3 id="troubleshooting-1" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting-1" aria-label="Permalink to “Troubleshooting”">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Meaning and next action</th></tr></thead><tbody><tr><td>Log says <code>turned off (FINK_ENABLED=false)</code></td><td>Fink is off in <code>.env</code>. Remove the line, then <code>arcsecond restart alerts</code>.</td></tr><tr><td>Log says <code>no topic ends in &#39;_ztf&#39; in FINK_TOPICS</code></td><td><code>FINK_TOPICS</code> lists no ZTF topic. Fix the list, or remove the line to use the default selection, then <code>arcsecond restart alerts</code>.</td></tr><tr><td>Started, but never <code>connection established</code></td><td>An outbound connection on port 24499 is likely blocked. Test from the host: <code>curl -v telnet://kafka-ztf.fink-broker.org:24499</code> (it must say <em>Connected</em>).</td></tr><tr><td>Log says <code>Fink ZTF refused access</code></td><td>Fink has closed its stream to anonymous readers, which it reserves the right to do. Update Arcsecond: a release will follow.</td></tr><tr><td>Log says <code>Installation not initialized</code></td><td>As for GCN: run <code>arcsecond start</code>, then <code>arcsecond restart alerts</code>.</td></tr></tbody></table><p>The alerts are Fink&#39;s work: credit <a href="https://fink-broker.org" target="_blank" rel="noreferrer">Fink</a> and ZTF when you use them.</p><h2 id="turning-it-off" tabindex="-1">Turning it off <a class="header-anchor" href="#turning-it-off" aria-label="Permalink to “Turning it off”">​</a></h2><p>Remove the service from your installation; the next start takes its container down:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --without-alerts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Your GCN credentials stay in <code>.env</code>; delete the two lines (and revoke the credential on gcn.nasa.gov) if you want them gone for good. <code>arcsecond setup --with-alerts</code> brings the service back at any time.</p>`,50)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
